#!/usr/bin/env bash
# Reproduce the real-validation numbers of 'c0' (model-v2x-track/routed-c0) from the checkpoints: realval-A/B inference of every used
# member with its committed post-processing, bag fusion, merge with model.yaml, official metric, comparison with
# validation/results/scorecard.json. Needs the prepared real validation data and the checkpoints. Generated by
# common/tools/reproduce_validation.py. Run on an idle GPU:
#   CUDA_VISIBLE_DEVICES=0 bash model-v2x-track/routed-c0/test/reproduce_c0_validation.sh
# The inference commands are independent: `python common/tools/reproduce_validation.py model-v2x-track/routed-c0 --tag c0 --jobs`
# prints them, one per line, for running several GPUs at once.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/../../.."      # the repository root (portable)
source common/env/activate.sh
mkdir -p model-v2x-track/routed-c0/validation/output/repro_c0
[ -s model-v2x-track/routed-c0/validation/output/repro_c0/voxelrcnn-ros-g1v6_tta_val.json ] || python common/tools/pcdet_predict.py model-v2x-track/voxelrcnn-ros-g1v6 --ckpt model-v2x-track/voxelrcnn-ros-g1v6/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split val --postprocess model-v2x-track/voxelrcnn-ros-g1v6/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-v2x-track/routed-c0/validation/output/repro_c0/voxelrcnn-ros-g1v6_tta_val.json
[ -s model-v2x-track/routed-c0/validation/output/repro_c0/voxelrcnn-ros-g1v6_tta_valB.json ] || python common/tools/pcdet_predict.py model-v2x-track/voxelrcnn-ros-g1v6 --ckpt model-v2x-track/voxelrcnn-ros-g1v6/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split valB --postprocess model-v2x-track/voxelrcnn-ros-g1v6/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-v2x-track/routed-c0/validation/output/repro_c0/voxelrcnn-ros-g1v6_tta_valB.json
[ -s model-v2x-track/routed-c0/validation/output/repro_c0/voxelrcnn-ros-g1v6d2_tta_val.json ] || python common/tools/pcdet_predict.py model-v2x-track/voxelrcnn-ros-g1v6d2 --ckpt model-v2x-track/voxelrcnn-ros-g1v6d2/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split val --postprocess model-v2x-track/voxelrcnn-ros-g1v6d2/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-v2x-track/routed-c0/validation/output/repro_c0/voxelrcnn-ros-g1v6d2_tta_val.json
[ -s model-v2x-track/routed-c0/validation/output/repro_c0/voxelrcnn-ros-g1v6d2_tta_valB.json ] || python common/tools/pcdet_predict.py model-v2x-track/voxelrcnn-ros-g1v6d2 --ckpt model-v2x-track/voxelrcnn-ros-g1v6d2/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split valB --postprocess model-v2x-track/voxelrcnn-ros-g1v6d2/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-v2x-track/routed-c0/validation/output/repro_c0/voxelrcnn-ros-g1v6d2_tta_valB.json
[ -s model-v2x-track/routed-c0/validation/output/repro_c0/dsvt-ros-g1v6_tta_val.json ] || python common/tools/pcdet_predict.py model-v2x-track/dsvt-ros-g1v6 --ckpt model-v2x-track/dsvt-ros-g1v6/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split val --postprocess model-v2x-track/dsvt-ros-g1v6/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-v2x-track/routed-c0/validation/output/repro_c0/dsvt-ros-g1v6_tta_val.json
[ -s model-v2x-track/routed-c0/validation/output/repro_c0/dsvt-ros-g1v6_tta_valB.json ] || python common/tools/pcdet_predict.py model-v2x-track/dsvt-ros-g1v6 --ckpt model-v2x-track/dsvt-ros-g1v6/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split valB --postprocess model-v2x-track/dsvt-ros-g1v6/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-v2x-track/routed-c0/validation/output/repro_c0/dsvt-ros-g1v6_tta_valB.json
[ -s model-v2x-track/routed-c0/validation/output/repro_c0/voxelrcnn-ros-g1v6_tta__3_val.json ] || python common/tools/pcdet_predict.py model-v2x-track/voxelrcnn-ros-g1v6 --ckpt model-v2x-track/voxelrcnn-ros-g1v6/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split val --postprocess model-v2x-track/voxelrcnn-ros-g1v6/test/postprocess_tta12.yaml --tta flip4+yaw+z+scale --out model-v2x-track/routed-c0/validation/output/repro_c0/voxelrcnn-ros-g1v6_tta__3_val.json
[ -s model-v2x-track/routed-c0/validation/output/repro_c0/voxelrcnn-ros-g1v6_tta__3_valB.json ] || python common/tools/pcdet_predict.py model-v2x-track/voxelrcnn-ros-g1v6 --ckpt model-v2x-track/voxelrcnn-ros-g1v6/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split valB --postprocess model-v2x-track/voxelrcnn-ros-g1v6/test/postprocess_tta12.yaml --tta flip4+yaw+z+scale --out model-v2x-track/routed-c0/validation/output/repro_c0/voxelrcnn-ros-g1v6_tta__3_valB.json
[ -s model-v2x-track/routed-c0/validation/output/repro_c0/voxelrcnn-ros-g1v6d2_tta__4_val.json ] || python common/tools/pcdet_predict.py model-v2x-track/voxelrcnn-ros-g1v6d2 --ckpt model-v2x-track/voxelrcnn-ros-g1v6d2/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split val --postprocess model-v2x-track/voxelrcnn-ros-g1v6d2/test/postprocess_tta12.yaml --tta flip4+yaw+z+scale --out model-v2x-track/routed-c0/validation/output/repro_c0/voxelrcnn-ros-g1v6d2_tta__4_val.json
[ -s model-v2x-track/routed-c0/validation/output/repro_c0/voxelrcnn-ros-g1v6d2_tta__4_valB.json ] || python common/tools/pcdet_predict.py model-v2x-track/voxelrcnn-ros-g1v6d2 --ckpt model-v2x-track/voxelrcnn-ros-g1v6d2/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split valB --postprocess model-v2x-track/voxelrcnn-ros-g1v6d2/test/postprocess_tta12.yaml --tta flip4+yaw+z+scale --out model-v2x-track/routed-c0/validation/output/repro_c0/voxelrcnn-ros-g1v6d2_tta__4_valB.json
[ -s model-v2x-track/routed-c0/validation/output/repro_c0/voxelrcnn-rosf-g1v6_tta_val.json ] || python common/tools/pcdet_predict.py model-v2x-track/voxelrcnn-rosf-g1v6 --ckpt model-v2x-track/voxelrcnn-rosf-g1v6/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split val --postprocess model-v2x-track/voxelrcnn-rosf-g1v6/test/postprocess_tta12.yaml --tta flip4+yaw+z+scale --out model-v2x-track/routed-c0/validation/output/repro_c0/voxelrcnn-rosf-g1v6_tta_val.json
[ -s model-v2x-track/routed-c0/validation/output/repro_c0/voxelrcnn-rosf-g1v6_tta_valB.json ] || python common/tools/pcdet_predict.py model-v2x-track/voxelrcnn-rosf-g1v6 --ckpt model-v2x-track/voxelrcnn-rosf-g1v6/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split valB --postprocess model-v2x-track/voxelrcnn-rosf-g1v6/test/postprocess_tta12.yaml --tta flip4+yaw+z+scale --out model-v2x-track/routed-c0/validation/output/repro_c0/voxelrcnn-rosf-g1v6_tta_valB.json
python common/tools/reproduce_validation.py model-v2x-track/routed-c0 --tag c0 --score
